// Lists of values made one value at a time (each an allocation that may collect): a big
// directory's names, and a long Tov array of strings handed to JavaScript, made while there is
// garbage about. An item the collector freed mid-list reads back wrong or crashes. The same
// package under Node.js prints the same.
const fs = require("fs");
const os = require("os");
const path = require("path");

exports.run = function run() {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "tov-gc-roots-"));
  const n = 4000;
  const want = [];
  for (let i = 0; i < n; i++) {
    const name = "entry-" + String(i).padStart(5, "0") + "-" + "x".repeat(i % 40);
    want.push(name);
    fs.writeFileSync(path.join(dir, name), "");
  }
  want.sort();
  let bad = 0;
  for (let round = 0; round < 20; round++) {
    for (let i = 0; i < 50; i++) new Array(5000).fill("garbage " + i);
    const names = round % 2 ? fs.readdirSync(dir, { withFileTypes: true }).map((d) => d.isFile() && d.name) : fs.readdirSync(dir);
    const got = names.slice().sort();
    if (got.length !== n || got.some((s, i) => s !== want[i])) bad++;
  }
  fs.rmSync(dir, { recursive: true, force: true });
  console.log("readdir", n, "entries, 20 rounds,", bad, "wrong");
};

// names[i] === "name-" + i for every i: how many aren't
exports.check = (names) => names.filter((s, i) => s !== "name-" + i).length;
